import{_ as o,c as r,o as t,a0 as s}from"./chunks/framework.CHkYM5Ax.js";const h=JSON.parse('{"title":"NestBase 技术栈面试题库","description":"","frontmatter":{},"headers":[],"relativePath":"resources/INTERVIEW_QA.md","filePath":"resources/INTERVIEW_QA.md","lastUpdated":1767754388000}'),a={name:"resources/INTERVIEW_QA.md"};function i(l,e,n,d,c,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="nestbase-技术栈面试题库" tabindex="-1">NestBase 技术栈面试题库 <a class="header-anchor" href="#nestbase-技术栈面试题库" aria-label="Permalink to &quot;NestBase 技术栈面试题库&quot;">​</a></h1><p>本文档整理了基于 <strong>NestBase</strong> 项目架构与技术栈的常见面试题及参考答案，帮助开发者在求职面试中更好地展示项目经验与技术深度。</p><h2 id="🏗️-架构设计-architecture" tabindex="-1">🏗️ 架构设计 (Architecture) <a class="header-anchor" href="#🏗️-架构设计-architecture" aria-label="Permalink to &quot;🏗️ 架构设计 (Architecture)&quot;">​</a></h2><h3 id="q1-为什么要使用-monorepo-架构-有哪些优缺点" tabindex="-1">Q1: 为什么要使用 Monorepo 架构？有哪些优缺点？ <a class="header-anchor" href="#q1-为什么要使用-monorepo-架构-有哪些优缺点" aria-label="Permalink to &quot;Q1: 为什么要使用 Monorepo 架构？有哪些优缺点？&quot;">​</a></h3><p><strong>参考答案</strong>： 本项目采用 <strong>pnpm workspace</strong> 实现 Monorepo 架构，主要基于以下考虑：</p><ol><li><strong>代码共享 (Code Sharing)</strong>：前后端（Backend/Frontend）共享 TypeScript 类型定义 (<code>.d.ts</code>) 和工具库 (<code>packages/utils</code>)，避免了 API 数据结构定义不一致的问题，修改一处类型，前后端同时报错提醒，极大提升了协作效率。</li><li><strong>统一依赖管理 (Dependency Management)</strong>：所有项目依赖统一管理，确保 <code>vue</code>、<code>typescript</code> 等核心库版本一致，避免版本冲突。pnpm 的软链接机制也大大节省了磁盘空间和安装时间。</li><li><strong>统一工程化配置 (Unified Configuration)</strong>：ESLint、Prettier、Git Hooks 等配置在根目录统一管理，确保整个团队的代码风格一致。</li></ol><p><strong>缺点与挑战</strong>：</p><ul><li><strong>权限控制</strong>：难以对仓库内的不同项目做细粒度写权限控制（通常全员拥有仓库写权限）。</li><li><strong>构建复杂度</strong>：Pipeline 需要能够识别变更的模块并进行增量构建（我们通过 pnpm filter 机制解决）。</li></ul><h3 id="q2-作为一个全栈项目-你的前后端交互标准是如何设计的" tabindex="-1">Q2: 作为一个全栈项目，你的前后端交互标准是如何设计的？ <a class="header-anchor" href="#q2-作为一个全栈项目-你的前后端交互标准是如何设计的" aria-label="Permalink to &quot;Q2: 作为一个全栈项目，你的前后端交互标准是如何设计的？&quot;">​</a></h3><p><strong>参考答案</strong>： 为了降低沟通成本，我们制定了严格的 <strong>API 治理标准</strong>：</p><ol><li><strong>RESTful 风格</strong>：严格遵循资源导向设计，如 <code>GET /users</code> (列表), <code>POST /users</code> (创建), <code>PATCH /users/:id</code> (更新)。</li><li><strong>统一响应结构</strong>：所有接口均返回统一格式 <code>{ code: 0, data: T, message: string }</code>，通过 NestJS 的 <strong>Global Interceptor</strong> 自动包装，无需在 Controller 中重复编写。</li><li><strong>全局异常处理</strong>：实现了 Global Exception Filter，将各类 HTTP 异常和业务异常统一转换为标准错误响应，前端只需监听非 0 的 code 即可。</li><li><strong>数据验证</strong>：后端通过 <code>class-validator</code> + <code>ValidationPipe</code> 在入口处拦截非法数据，前端表单验证规则部分也可复用这些定义。</li></ol><hr><h2 id="🔙-后端技术-nestjs-prisma" tabindex="-1">🔙 后端技术 (NestJS &amp; Prisma) <a class="header-anchor" href="#🔙-后端技术-nestjs-prisma" aria-label="Permalink to &quot;🔙 后端技术 (NestJS &amp; Prisma)&quot;">​</a></h2><h3 id="q3-你的-rbac-权限系统是如何设计的-如何实现细粒度控制" tabindex="-1">Q3: 你的 RBAC 权限系统是如何设计的？如何实现细粒度控制？ <a class="header-anchor" href="#q3-你的-rbac-权限系统是如何设计的-如何实现细粒度控制" aria-label="Permalink to &quot;Q3: 你的 RBAC 权限系统是如何设计的？如何实现细粒度控制？&quot;">​</a></h3><p><strong>参考答案</strong>： 本项目实施了 <strong>RBAC (Role-Based Access Control)</strong> 模型，并扩展了细粒度权限控制：</p><ol><li><strong>模型设计</strong>： <ul><li><strong>用户 (User)</strong>：可以拥有多个角色。</li><li><strong>角色 (Role)</strong>：权限的集合，用于菜单可见性控制。</li><li><strong>权限 (Permission)</strong>：具体的操作点（如 <code>user.create</code>, <code>user.delete</code>）。</li><li><strong>菜单 (Menu)</strong>：与角色关联，决定左侧导航栏的渲染。</li></ul></li><li><strong>鉴权机制 (Guard)</strong>： <ul><li><strong>认证</strong>：<code>JwtAuthGuard</code> 验证 Token 解析出 User。</li><li><strong>角色检查</strong>：<code>RolesGuard</code> 配合 <code>@Roles(&#39;ADMIN&#39;)</code> 装饰器，控制粗粒度访问。</li><li><strong>权限检查</strong>：实现了<strong>AOP 切面</strong>的 <code>PermissionsGuard</code>，配合自定义装饰器 <code>@RequirePermissions(&#39;user.create&#39;)</code>，在 Controller 方法执行前即拦截无权请求。</li></ul></li></ol><h3 id="q4-为什么选择-prisma-而不是-typeorm" tabindex="-1">Q4: 为什么选择 Prisma 而不是 TypeORM？ <a class="header-anchor" href="#q4-为什么选择-prisma-而不是-typeorm" aria-label="Permalink to &quot;Q4: 为什么选择 Prisma 而不是 TypeORM？&quot;">​</a></h3><p><strong>参考答案</strong>：</p><ol><li><strong>类型安全 (Type Safety)</strong>：Prisma 会根据 schema 自动生成强类型的 Client，查询结果自带类型推导，这与我们全栈 TypeScript 的理念完美契合。TypeORM 虽然也支持 TS，但在复杂关联查询的类型推导上不如 Prisma 智能。</li><li><strong>开发体验</strong>：Prisma Schema (<code>schema.prisma</code>) 定义直观清晰，<code>prisma migrate</code> 数据库迁移工作流比 TypeORM 的同步机制更可靠可控。</li><li><strong>查询直观</strong>：Prisma 的查询 API 更贴近对象操作 (Object-based)，而非 SQL 拼接，代码可读性更高。</li></ol><h3 id="q5-在-nestjs-中如何处理循环依赖" tabindex="-1">Q5: 在 NestJS 中如何处理循环依赖？ <a class="header-anchor" href="#q5-在-nestjs-中如何处理循环依赖" aria-label="Permalink to &quot;Q5: 在 NestJS 中如何处理循环依赖？&quot;">​</a></h3><p><strong>参考答案</strong>： (结合项目实际) 在 Auth 模块和 User 模块相互引用时遇到了这个问题。</p><ul><li><strong>解决方案</strong>：使用 <code>forwardRef()</code>。在 Module 导入时使用 <code>imports: [forwardRef(() =&gt; UsersModule)]</code>，并在 Service 注入时使用 <code>@Inject(forwardRef(() =&gt; UsersService))</code>。这延迟了模块的解析，允许 NestJS 解决循环引用。</li></ul><hr><h2 id="🎨-前端技术-vue-3" tabindex="-1">🎨 前端技术 (Vue 3) <a class="header-anchor" href="#🎨-前端技术-vue-3" aria-label="Permalink to &quot;🎨 前端技术 (Vue 3)&quot;">​</a></h2><h3 id="q6-前端动态路由-菜单权限-是如何实现的" tabindex="-1">Q6: 前端动态路由（菜单权限）是如何实现的？ <a class="header-anchor" href="#q6-前端动态路由-菜单权限-是如何实现的" aria-label="Permalink to &quot;Q6: 前端动态路由（菜单权限）是如何实现的？&quot;">​</a></h3><p><strong>参考答案</strong>： 这是一个典型的 <strong>后端驱动 (Backend-Driven)</strong> 动态路由方案：</p><ol><li><strong>路由定义</strong>：前端代码中只保留基础路由（如登录页、404），所有业务路由组件在前端注册，但路径关系由后端管理。</li><li><strong>初始化流程</strong>： <ul><li>用户登录后，调用 <code>/auth/user-routes</code> 接口。</li><li>后端根据用户角色计算出其可访问的菜单树。</li><li>前端拿到菜单树后，递归遍历，将 Server 端的组件 key 映射为前端真实的 import 组件。</li><li>使用 <code>router.addRoute()</code> 动态挂载路由。</li></ul></li><li><strong>优势</strong>：权限变更无需重新发布前端，管理员在后台配置菜单即可实时生效。</li></ol><h3 id="q7-你的项目中用到了哪些-vue-3-的新特性" tabindex="-1">Q7: 你的项目中用到了哪些 Vue 3 的新特性？ <a class="header-anchor" href="#q7-你的项目中用到了哪些-vue-3-的新特性" aria-label="Permalink to &quot;Q7: 你的项目中用到了哪些 Vue 3 的新特性？&quot;">​</a></h3><p><strong>参考答案</strong>：</p><ol><li><strong>Composition API (Script Setup)</strong>：全面使用 <code>&lt;script setup&gt;</code> 语法糖，逻辑复用更方便（如封装了 <code>useTable</code>, <code>useForm</code> 等 Hooks）。</li><li><strong>Custom Hooks</strong>： <ul><li><strong><code>useTable</code></strong>：封装了分页、搜索、Loading 状态、数据获取的通用逻辑，使得每个管理页面的代码量减少了 50% 以上。</li><li><strong><code>useBoolean</code></strong>：优雅处理 Modal/Drawer 的开关状态。</li></ul></li><li><strong>Teleport</strong>：用于封装全局的 Modal 弹窗组件，避免层级嵌套导致的 z-index 问题。</li></ol><hr><h2 id="🛠️-工程化与运维" tabindex="-1">🛠️ 工程化与运维 <a class="header-anchor" href="#🛠️-工程化与运维" aria-label="Permalink to &quot;🛠️ 工程化与运维&quot;">​</a></h2><h3 id="q8-项目是如何部署的" tabindex="-1">Q8: 项目是如何部署的？ <a class="header-anchor" href="#q8-项目是如何部署的" aria-label="Permalink to &quot;Q8: 项目是如何部署的？&quot;">​</a></h3><p><strong>参考答案</strong>：</p><ol><li><strong>Docker 化</strong>：编写了 <code>Dockerfile</code>，采用多阶段构建 (Multi-stage Build) 减小镜像体积，只保留 <code>dist</code> 和生产依赖。</li><li><strong>GitHub Actions (CI/CD)</strong>： <ul><li>配置了自动化工作流，当代码推送到 <code>main</code> 分支时，自动运行 Lint 检查和 Build。</li><li>文档站点 (VitePress) 自动打包并发布到 GitHub Pages。</li></ul></li><li><strong>环境变量管理</strong>：严格区分 <code>.env.development</code> 和 <code>.env.production</code>，敏感信息（如数据库密码、JWT Secret）通过 CI/CD 的 Secrets 注入，不提交到代码仓库。</li></ol><h3 id="q9-遇到了什么难点-如何解决的" tabindex="-1">Q9: 遇到了什么难点？如何解决的？ <a class="header-anchor" href="#q9-遇到了什么难点-如何解决的" aria-label="Permalink to &quot;Q9: 遇到了什么难点？如何解决的？&quot;">​</a></h3><p><strong>参考答案 (可根据您的实际体会调整)</strong>：</p><ul><li><strong>难点</strong>：在做 RBAC 时，如何处理&quot;父子菜单权限级联&quot;与&quot;按钮级权限&quot;的关系。</li><li><strong>解决</strong>：将&quot;菜单&quot;和&quot;权限点&quot;解耦。菜单控制页面进入权限，权限点控制页面内的按钮（增删改）。在数据库设计上，角色与菜单表关联，同时角色与权限表关联，两者独立又互补，实现了最大的灵活性。</li></ul><hr><h2 id="🌟-简历加分项话术" tabindex="-1">🌟 简历加分项话术 <a class="header-anchor" href="#🌟-简历加分项话术" aria-label="Permalink to &quot;🌟 简历加分项话术&quot;">​</a></h2><ul><li><strong>全栈视野</strong>：能独立完成从数据库设计(Schema)到后端 API(NestJS)再到前端交互(Vue3)的完整闭环开发。</li><li><strong>规范意识</strong>：推崇代码规范，项目中严格配置了 ESLint, Prettier 和 Git Commit 规范。</li><li><strong>文档能力</strong>：编写了详细的 API 文档和开发指南，认为良好的文档是工程质量的重要组成部分。</li></ul>',41)])])}const p=o(a,[["render",i]]);export{h as __pageData,p as default};
